from typing import List
from math import gcd
from collections import defaultdict, deque

class Solution:
    def canTraverseAllPairs(self, nums: List[int]) -> bool:
        n = len(nums)
        if n == 1:
            return False  # only one element, no pair to consider

        # If any element is 1, it cannot connect to anything (gcd(1, x) = 1 for x>1)
        # If there are multiple 1s, they cannot connect to each other (gcd(1,1)=1)
        if 1 in nums:
            return True

        # We need to check if the graph where edges exist between indices i, j if gcd(nums[i], nums[j]) > 1 is fully connected.
        # Since n up to 1e5, we cannot check all pairs.
        # Instead, factorize numbers and build connectivity via prime factors.
        # Create a bipartite graph between indices and prime factors.
        # Indices are connected if they share a prime factor.
        # We can use Union-Find (DSU) to merge indices that share a prime factor.

        max_val = max(nums)
        # Sieve for smallest prime factor (SPF) up to max_val
        spf = list(range(max_val + 1))
        for i in range(2, int(max_val**0.5) + 1):
            if spf[i] == i:
                for j in range(i*i, max_val + 1, i):
                    if spf[j] == j:
                        spf[j] = i

        # DSU for indices
        parent = list(range(n))
        rank = [0] * n

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(x, y):
            rx, ry = find(x), find(y)
            if rx == ry:
                return
            if rank[rx] < rank[ry]:
                parent[rx] = ry
            elif rank[rx] > rank[ry]:
                parent[ry] = rx
            else:
                parent[ry] = rx
                rank[rx] += 1

        # Map prime factor to first index that has it
        prime_to_index = {}

        for idx, val in enumerate(nums):
            # factorize val using spf
            x = val
            factors = set()
            while x > 1:
                p = spf[x]
                factors.add(p)
                while x % p == 0:
                    x //= p
            for p in factors:
                if p in prime_to_index:
                    union(idx, prime_to_index[p])
                else:
                    prime_to_index[p] = idx

        # Check if all indices belong to the same component
        root = find(0)
        for i in range(1, n):
            if find(i) != root:
                return True  # there exists at least one pair that cannot traverse

        return False
